import datetime

from pypara.accounting.generic import Balance
from pypara.accounting.journaling import Direction, Posting
from pypara.accounting.ledger import Ledger
from pypara.commons.numbers import Quantity


class _StubAccount:
    """Minimal stand-in satisfying the ``Account`` protocol."""

    def __init__(self, code: str = "1000", name: str = "Cash") -> None:
        self._code = code
        self._name = name

    @property
    def code(self):
        return self._code

    @property
    def name(self):
        return self._name

    @property
    def type(self):
        return None

    @property
    def coa(self):
        return None

    @property
    def parent(self):
        return None


def _get_direction(names, target_value):
    for name in names:
        if hasattr(Direction, name):
            return getattr(Direction, name)
    for member in Direction:
        try:
            if member.value == target_value:
                return member
        except Exception:
            continue
    members = list(Direction)
    return members[0] if target_value > 0 else members[-1]


DEBIT = _get_direction(("DEBIT", "INC", "INCREASING", "INCREASE", "DR"), 1)
CREDIT = _get_direction(("CREDIT", "DEC", "DECREASING", "DECREASE", "CR"), -1)


def _make_posting(account, amount, direction=DEBIT):
    return Posting(
        journal=None,
        date=datetime.date(2022, 1, 1),
        account=account,
        direction=direction,
        amount=Quantity(amount),
    )


def _make_ledger(**kwargs):
    account = kwargs.pop("account", _StubAccount())
    initial = kwargs.pop("initial", Balance(datetime.date(2022, 1, 1), Quantity(1000)))
    return Ledger(account=account, initial=initial, **kwargs)


def test_direction_members_have_opposite_signed_values():
    assert DEBIT is not CREDIT
    assert DEBIT.value == 1
    assert CREDIT.value == -1


def test_last_balance_falls_back_to_initial_value_when_entries_empty():
    ledger = _make_ledger()

    assert ledger.entries == []
    assert ledger._last_balance == Quantity(1000)


def test_add_first_entry_uses_initial_balance():
    ledger = _make_ledger()
    posting = _make_posting(ledger.account, 250)

    entry = ledger.add(posting)

    assert entry.ledger is ledger
    assert entry.posting is posting
    assert entry.balance == Quantity(1250)
    assert ledger.entries == [entry]
    assert ledger._last_balance == Quantity(1250)


def test_add_accumulates_on_previous_entry_balance_debit():
    ledger = _make_ledger()
    account = ledger.account
    first = ledger.add(_make_posting(account, 250))
    second = ledger.add(_make_posting(account, 500))

    assert first.balance == Quantity(1250)
    assert second.balance == Quantity(1750)
    assert ledger.entries == [first, second]
    assert ledger.entries[-1] is second
    assert ledger._last_balance == Quantity(1750)


def test_add_accumulates_on_previous_entry_balance_credit():
    ledger = _make_ledger()
    account = ledger.account
    first = ledger.add(_make_posting(account, 1000))
    second = ledger.add(_make_posting(account, 250, direction=CREDIT))

    assert first.balance == Quantity(2000)
    assert second.balance == Quantity(1750)
    assert ledger._last_balance == Quantity(1750)


def test_add_returns_new_entry_and_does_not_mutate_previous_entries():
    ledger = _make_ledger()
    account = ledger.account
    first = ledger.add(_make_posting(account, 100))
    first_balance = first.balance

    second = ledger.add(_make_posting(account, 100))

    assert second is not first
    assert first.balance == first_balance == Quantity(1100)
    assert second.balance == Quantity(1200)
    assert len(ledger.entries) == 2


def test_last_balance_with_entries_returns_last_entry_balance():
    ledger = _make_ledger()
    ledger.add(_make_posting(ledger.account, 100))
    last = ledger.add(_make_posting(ledger.account, 400))

    assert ledger._last_balance == last.balance == Quantity(1500)
