def test_compile_general_ledger_program_wires_readers_and_builder(monkeypatch, period):
    calls = {}
    sentinel_ledger = GeneralLedger(period, {})
    initial_balances = {"dummy": "initial"}
    journal_entries = ["entry-1", "entry-2"]

    def fake_read_initial_balances(p):
        calls["initial"] = p
        return initial_balances

    def fake_read_journal_entries(p):
        calls["journal"] = p
        return journal_entries

    def fake_build_general_ledger(p, journal, initial):
        calls["build"] = (p, journal, initial)
        return sentinel_ledger

    monkeypatch.setattr(
        "pypara.accounting.ledger.build_general_ledger", fake_build_general_ledger
    )

    program = compile_general_ledger_program(
        fake_read_initial_balances, fake_read_journal_entries
    )

    assert callable(program)

    result = program(period)

    assert result is sentinel_ledger
    assert calls["initial"] is period
    assert calls["journal"] is period
    assert calls["build"] == (period, journal_entries, initial_balances)

    # Confirm no state leaked into the module under test.
    from pypara.accounting import ledger as ledger_module

    assert ledger_module.build_general_ledger is not fake_build_general_ledger


def test_compiled_program_readers_called_once_each(period):
    reader_calls = {"initial": 0, "journal": 0}

    def read_initial_balances(p):
        reader_calls["initial"] += 1
        return {}

    def read_journal_entries(p):
        reader_calls["journal"] += 1
        return []

    program = compile_general_ledger_program(
        read_initial_balances, read_journal_entries
    )

    first = program(period)
    second = program(period)

    assert reader_calls == {"initial": 2, "journal": 2}
    assert isinstance(first, GeneralLedger)
    assert isinstance(second, GeneralLedger)
    assert first is not second
    assert first.period == period
    assert second.period == period
    assert first.ledgers == {}
    assert second.ledgers == {}


def test_compiled_program_matches_direct_build(period):
    program = compile_general_ledger_program(lambda p: {}, lambda p: [])

    ledger = program(period)
    expected = build_general_ledger(period, [], {})

    assert isinstance(ledger, GeneralLedger)
    assert ledger.period == expected.period
    assert ledger.ledgers == expected.ledgers == {}
